div.g:evaluate:
var uc_heading = gs.getMessage('User Criteria');

if(!finalResults.isDomainSeparationActive){
	if(ucResults.summary == 4) 
		uc_heading = gs.getMessage('How to Provide Access');
	else 
		uc_heading = gs.getMessage('User Criteria Assigned');
}

j:if.g:evaluate:
var table_note = "";

if(ucResults.results.length == 0){
	if(isArticle == 'true')
		table_note = gs.getMessage('To provide access to the knowledge article, add an appropriate user criteria to the {1} knowledge base for {0}.',links);
	else
		table_note = gs.getMessage('To provide access to the knowledge base, add an appropriate user criteria to the {1} knowledge base for {0}.',links);
}
else {
	if(isArticle == 'true')
		table_note = gs.getMessage('To provide access to article {2} in knowledge base {1}, add {0} to one or more of the following user criteria set at article or knowledge base level.',links);
	else
		table_note = gs.getMessage('To provide access to knowledge base ({1}), add {0} to one or more of the following user criteria.',links);	
}

